from pathlib import Path
import json,html
R=Path(__file__).resolve().parent.parent; S=R/'source'; icons=json.loads((S/'icons.json').read_text())
def I(n): return icons[n]
def link(text,target,cls='text-link'): return f'<a class="{cls}" href="{target}.html">{text}</a>'
def B(text,target):return link(text+' '+I('ArrowRight'),target,'button')
def image(name,alt,cls=''):return f'<img class="{cls}" src="../assets/{name}.png" alt="{alt}">'
def field(label,value='',typ='text',error=False):
 ident=label.lower().replace(' ','-').replace('(','').replace(')','');return f'<div class="field"><label for="{ident}">{label}</label><input id="{ident}" type="{typ}" value="{html.escape(value)}"'+(' aria-invalid="true" aria-describedby="pin-error"' if error else '')+'></div>'
def info(title,text,kind=''):return f'<div class="info {kind}">{I("Info")}<div><strong>{title}</strong><p>{text}</p></div></div>'
def header():return f'''<div class="announcement">Everyday staples. Ingredients in plain sight.</div><header class="header"><div class="wrap header-inner"><a class="icon-link mobile-menu" href="03-collection.html" aria-label="Browse pantry shelves">{I('Menu')}</a><a class="wordmark" href="01-home-top.html"><b>pantry.</b></a><nav class="nav" aria-label="Main">{link('Pantry shelves','03-collection','')}{link('Ingredient guide','05-product-facts','')}{link('Recipes','06-product-continuation','')}{link('Our pantry','02-home-bottom','')}</nav><div class="tools"><a class="icon-link search-tool" href="03-collection.html" aria-label="Search pantry">{I('Search')}</a><a class="icon-link account-tool" href="12-profile.html" aria-label="Your account">{I('UserRound')}</a><a class="icon-link" href="07-cart.html" aria-label="Cart, 3 packs">{I('ShoppingBag')}<small>3</small></a></div></div></header>'''
def footer():return f'''<footer class="footer"><div class="wrap"><div class="footer-grid"><div><a class="wordmark" href="01-home-top.html"><b>pantry.</b></a><p>Small staples. Everyday possibilities.</p><p>Read the ingredients. Choose your pack.<br>Make it yours in the kitchen.</p></div><div><h3>Explore</h3>{link('Pantry shelves','03-collection','')}{link('Ingredient guide','05-product-facts','')}{link('Recipes','06-product-continuation','')}</div><div><h3>Useful details</h3>{link('Storage guide','05-product-facts','')}{link('Shipping & returns','06-product-continuation','')}{link('Order support','14-order-detail','')}</div><div><h3>Your account</h3>{link('Sign in','10-sign-in','')}{link('Your orders','13-orders','')}{link('Saved addresses','15-addresses','')}</div></div><div class="footer-bottom"><span>© 2026 Pantry · Fictional visual reference</span><span>India / INR ₹ · Privacy · Terms</span></div></div></footer>'''
def crumb(last):return f'<nav class="crumb" aria-label="Breadcrumb">{link("Home","01-home-top","")}{I("ChevronRight")}{link("Pantry shelves","03-collection","")}{I("ChevronRight")}<span>{last}</span></nav>'
def search():return f'<label class="search">{I("Search")}<input aria-label="Search products and ingredients" placeholder="Search products or ingredients"></label>'
def shelf(name,sub,icon):return f'<a class="shelf" href="03-collection.html">{I(icon)}<span><strong>{name}</strong><small>{sub}</small></span>{I("ArrowRight")}</a>'
def row(rice=False,big=False):
 title='Basmati rice' if rice else 'Split red lentils';pack='1 kg' if rice else ('500 g' if big else '250 g');price='220' if rice else ('340' if big else '180');unit='₹22 / 100 g' if rice else ('₹68 / 100 g' if big else '₹72 / 100 g');target='product-rice' if rice else '04-product-main';img='basmati-rice' if rice else 'red-lentils'
 return f'''<article class="product-row">{link(image(img,title+' in an unprinted pouch'),target,'')}<div><p class="eyebrow">{'Rice & grains' if rice else 'Pulses & lentils'}</p><h3>{link(title,target,'')}</h3><p>{pack} net · 1 pack</p><div class="row-bottom"><div><div class="price">₹{price}</div><small class="muted">{unit}</small></div>{link('Choose pack '+I('ArrowRight'),target,'button secondary')}</div></div></article>'''
def context():return f'<div class="context">{image("red-lentils","Split red lentils pouch")}<div><h3>Split red lentils</h3><p>250 g / pack · 2 packs selected · ₹360</p></div>{link("Back to selection "+I("ArrowRight"),"04-product-main")}</div>'
def facts():return '''<div class="fact"><strong>Ingredients</strong><p>Split red lentils (100%).</p></div><div class="fact"><strong>Allergen information</strong><p>Not supplied by the merchant.</p></div>'''+info('Unknown is not allergen-free','If this matters for your diet, ask the merchant before buying.','warning')+'''<div class="fact"><strong>Storage</strong><p>Store in a cool, dry place. Once opened, transfer to an airtight container.</p></div>'''
def qty(n=2):return f'<div class="qty" aria-label="Pack quantity"><button aria-label="Decrease packs">{I("Minus")}</button><span>{n}</span><button aria-label="Increase packs">{I("Plus")}</button></div>'
def summary(shipping=True,checkout=False):return f'''<aside class="summary"><h2>{'Your order' if checkout else 'Cart summary'}</h2><div class="mini-line">{image('red-lentils','Lentils')}<div><strong>Split red lentils</strong><p>250 g × 2 · 500 g net</p></div><strong>₹360</strong></div><div class="mini-line">{image('basmati-rice','Basmati rice')}<div><strong>Basmati rice</strong><p>1 kg × 1 · 1 kg net</p></div><strong>₹220</strong></div><div class="summary-row"><span>3 packs · 1.5 kg total net</span></div><div class="summary-row"><span>Subtotal</span><span>₹580</span></div><div class="summary-row"><span>Shipping</span><span>{'₹60' if shipping else 'At checkout'}</span></div><div class="summary-row"><span>Tax</span><span>Included</span></div><div class="summary-row total"><span>{'Total' if shipping else 'Subtotal'}</span><span>{'₹640' if shipping else '₹580'}</span></div><p class="small">{'Sample shipping quote for the selected address. No delivery date has been supplied.' if shipping else 'Shipping is calculated for your address at shared checkout.'}</p>{'' if checkout else B('Continue to checkout','08-checkout-address')}<p class="small">{I('LockKeyhole')} {'Mock provider · Visual fixture' if checkout else 'Continue through LetBuyy shared checkout'}</p></aside>'''
def line(rice=False):return f'''<div class="cart-line">{image('basmati-rice' if rice else 'red-lentils','Basmati rice' if rice else 'Red lentil pack')}<div><h3>{'Basmati rice' if rice else 'Split red lentils'}</h3><p>{'1 kg' if rice else '250 g'} / pack · SKU {'P-RICE-1K' if rice else 'P-LENT-250'}</p><p>{'1 pack · 1 kg total net · ₹220 / pack' if rice else '2 packs · 500 g total net · ₹180 / pack'}</p><div class="cart-controls">{qty(1 if rice else 2)}<button class="text-link" style="background:none;border:0">Remove</button></div></div><strong>₹{'220' if rice else '360'}</strong></div>'''
def order_line(rice=False):
 return f'''<article class="cart-line order-item">{image('basmati-rice' if rice else 'red-lentils','Basmati rice' if rice else 'Red lentil pack')}<div><h3>{'Basmati rice' if rice else 'Split red lentils'}</h3><p>{'1 kg' if rice else '250 g'} / pack · SKU {'P-RICE-1K' if rice else 'P-LENT-250'}</p><p>{'1 pack · 1 kg total net · ₹220 / pack' if rice else '2 packs · 500 g total net · ₹180 / pack'}</p></div><strong>₹{'220' if rice else '360'}</strong></article>'''
address='<address class="address">Mira Example<br>14 Sample Lane, Flat 2<br>Example Nagar, Bengaluru<br>Karnataka 560001, India</address>'
def account(active):
 names=[('Overview','12-profile','UserRound'),('Orders','13-orders','Package'),('Addresses','15-addresses','MapPin')]
 return f'<nav class="account-nav" aria-label="Account">'+''.join(link(I(i)+' '+n,t,'selected' if n==active else '') for n,t,i in names)+link(I('LogOut')+' Sign out','10-sign-in','')+'</nav>'
def account_shell(title,sub,active,content):return f'''{header()}<main class="wrap"><div class="account-intro"><div><p class="eyebrow">Your Pantry account</p><h1>{title}</h1><p>{sub}</p></div>{link('Back to shopping '+I('ArrowRight'),'03-collection')}</div><div class="account-layout">{account(active)}<div class="account-main">{content}</div></div></main>{footer()}'''
scenes=[]
def add(id,title,body,route,mission):
 scenes.append(dict(id=id,title=title,route=route,mission=mission,source=f'source/{id}.html'))
 (S/f'{id}.html').write_text(f'<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pantry · {title} · Visual reference</title><link rel="stylesheet" href="styles.css"></head><body><a href="#main" class="skip" style="position:absolute;left:-10000px">Skip to content</a>{body}<script src="prototype.js"></script></body></html>')
add('01-home-top','Home · seasonal staples',header()+f'''<main id="main" class="wrap"><section class="section"><div class="hero"><div class="hero-copy"><p class="eyebrow">The everyday pantry</p><h1>Good things<br>start with staples.</h1><p>Rice, pulses and the ingredients you reach for. Find your shelf, read the details, choose your pack.</p>{B('Explore pantry shelves','03-collection')}</div>{image('staples-still-life','Bowls of dry red lentils and rice on a linen-covered kitchen table')}</div><nav class="shelves" aria-label="Pantry shelves">{shelf('Pulses & lentils','For everyday cooking','CookingPot')}{shelf('Rice & grains','Choose your staple','Leaf')}{shelf('Ingredient guide','Read before you buy','BookOpen')}{shelf('Storage & use','From pack to pantry','Package')}</nav></section><section class="section" style="padding-top:12px"><div class="section-head"><div><p class="eyebrow">Stock the shelf</p><h2>A little everyday order.</h2></div>{link('View all staples '+I('ArrowRight'),'03-collection')}</div><div class="shelf-grid">{row()}{row(True)}</div></section><div class="state-note">Explore the ingredients, pack sizes and preparation notes behind each staple.</div></main>''','/','Choose a useful shelf without an oversized campaign blocking product access.')
add('02-home-bottom','Home · ingredients & everyday use',header()+f'''<main id="main" class="wrap"><section class="section"><div class="feature">{image('red-lentils','Single unprinted lentil pouch, illustrative packaging')}<div><p class="eyebrow">One ingredient, many possibilities</p><h2>Meet the staple.<br>Know what is inside.</h2><p>Split red lentils, with ingredients and supplied storage notes in one place. Choose the pack that fits your kitchen.</p><span class="pill">250 g / pack</span> <span class="pill">₹180 / pack</span>{info('Allergen details','Not supplied for this product. Ask the merchant if you need this information.','warning')}{B('Read the product details','04-product-main')}</div></div></section><section class="section"><div class="section-head"><div><p class="eyebrow">From shelf to saucepan</p><h2>Start with two staples.</h2><p>Recipe inspiration and products remain separate choices.</p></div>{link('Read the pantry notes '+I('ArrowRight'),'06-product-continuation')}</div><div class="shelf-grid"><div class="panel"><h3>A simple lentil & rice pot</h3><p style="margin:12px 0">Read preparation notes, then choose the ingredients you want. No automatic bundle.</p>{link('See preparation notes','06-product-continuation')}</div>{row(True)}</div></section><div class="facts-inline"><div>{I('Package')}<h3>Choose the right pack</h3><p>Pack count and total net quantity stay distinct.</p></div><div>{I('BookOpen')}<h3>Read the label details</h3><p>Supplied ingredients and known information, clearly stated.</p></div><div>{I('Truck')}<h3>Check shipping for you</h3><p>Rates are shown for your address at checkout.</p></div></div></main>'''+footer(),'/#continuation','Continue the same homepage into product education, separate recipe links and honest service information.')
add('03-collection','Pantry shelves · collection & search',header()+f'''<main id="main" class="wrap">{crumb('Everyday staples')}<div class="catalog-title"><div><p class="eyebrow">Choose a shelf. Read the details.</p><h1>Everyday staples</h1><p>Pack sizes and ingredients, before you add.</p></div>{search()}</div><nav class="category-tabs" aria-label="Shelf categories">{link('All staples','03-collection','selected')}{link('Pulses & lentils','03-collection','')}{link('Rice & grains','03-collection','')}</nav><div class="filter-bar"><span>{I('SlidersHorizontal')} Narrow your shelf</span><select aria-label="Pack weight"><option>Pack weight · Any</option><option>250 g</option><option>1 kg</option></select><select aria-label="Price"><option>Price · Any</option></select><select class="push" aria-label="Sort"><option>Featured</option><option>Price: low to high</option></select></div><div class="section-head"><h2>Pulses & lentils</h2><span class="small muted">1 product · 2 pack sizes</span></div><div class="shelf-grid">{row()}<div class="panel"><h3>Read before you choose</h3><p>Dietary suitability cannot be inferred from a product name. Open a product for supplied ingredients and allergen information.</p>{link('How we show food facts','05-product-facts')}</div></div><div class="section-head" style="margin-top:32px"><h2>Rice & grains</h2><span class="small muted">1 product</span></div><div class="shelf-grid">{row(True)}</div><nav class="pagination" aria-label="Pagination"><p>2 products · Page 1 of 1</p><a href="03-collection.html" aria-current="page">1</a></nav>{info('No matching products?','Keep your search, remove a pack-weight filter, or return to All staples. Alternative items must be shown separately from matches.')}</main>'''+footer(),'/collections/staples','Scan shelf rows with net quantity beside price; filters/sort require real query contracts.')
add('04-product-main','Product · pack selection',header()+f'''<main id="main" class="wrap">{crumb('Split red lentils')}<div class="mobile-product-intro"><p class="eyebrow">Pulses & lentils</p><h1>Split red lentils</h1><p><strong>₹180 / pack</strong> · 250 g net / pack</p></div><div class="pdp-grid"><div><div class="pdp-photo">{image('red-lentils','Unprinted kraft pouch of split red lentils')}</div><p class="caption">Illustrative packaging · read the supplied facts</p></div><section class="ingredients"><p class="eyebrow">Read before choosing</p><h2>Inside the pack</h2>{facts()}{link('All product facts '+I('ArrowRight'),'05-product-facts')}</section><section class="purchase"><p class="eyebrow">Pulses & lentils</p><h1>Split red lentils</h1><div class="price">₹180 <small class="muted">/ pack</small></div><p class="small">250 g net / pack · ₹72 / 100 g<br>Price includes tax</p><fieldset class="option-group"><legend>Pack size</legend><div class="options"><label class="option selected"><input type="radio" name="pack" checked>250 g</label><label class="option unavailable"><input type="radio" name="pack" disabled>500 g · unavailable</label></div></fieldset><label class="small">Number of packs</label><div class="purchase-action">{qty()}</div><div class="pack-math"><span>2 packs × 250 g</span><strong>500 g total net · ₹360</strong></div><p class="available">{I('Check')} Available in selected pack size</p><div class="purchase-action">{B('Add 2 packs · ₹360','07-cart')}</div><p class="small">Shipping calculated at checkout.</p>{link('Storage & preparation','05-product-facts')}</section></div><div class="state-note">Continue on this product for preparation notes, storage details and independent pantry pairings.</div></main>''','/products/split-red-lentils','See ingredients and unknown allergens before submitting 2 × 250g, preserving 500g net and ₹360.')
add('05-product-facts','Product · ingredients, storage & preparation',header()+f'''<main id="main" class="wrap">{context()}<p class="eyebrow">Product facts · merchant-supplied fixture</p><h1 style="margin:12px 0 30px">Know your staple.</h1><div class="decision-grid"><section><h2>Ingredients & pack details</h2><table class="fact-table"><tbody><tr><th>Ingredients</th><td>Split red lentils (100%)</td></tr><tr><th>Allergens</th><td><strong>Not supplied.</strong><br>No allergen-free claim is made.</td></tr><tr><th>Net quantity</th><td>250 g per pack</td></tr><tr><th>Selected quantity</th><td>2 packs · 500 g total net</td></tr><tr><th>Unit price</th><td>₹72 / 100 g · ₹180 / 250 g pack</td></tr><tr><th>Storage</th><td>Cool, dry place; airtight container after opening.</td></tr><tr><th>Nutrition information</th><td>Not supplied for this product.</td></tr></tbody></table>{info('If you need allergen information','Contact the merchant before buying. Missing information must stay unknown.','warning')}</section><aside><div class="panel"><p class="eyebrow">Preparation notes</p><h3>From pack to saucepan</h3><ol class="steps"><li><div><strong>Measure & rinse</strong><p>Measure the amount you need and rinse before cooking.</p></div></li><li><div><strong>Cook until tender</strong><p>Use your chosen recipe for water, time and seasoning.</p></div></li><li><div><strong>Check the package</strong><p>Follow current on-pack instructions where supplied.</p></div></li></ol></div><div class="panel"><h3>Shelf-life information</h3><p>No batch or current expiry date has been supplied in this reference. Check the received package.</p></div></aside></div>{link('Continue to pantry pairings '+I('ArrowRight'),'06-product-continuation')}</main>''','/products/split-red-lentils#facts','Present ingredients, absent allergen/nutrition information, quantity units and supplied storage without invented health claims.')
add('06-product-continuation','Product · use, pairings & policy',header()+f'''<main id="main" class="wrap">{context()}<section class="feature"><div><p class="eyebrow">A starting point for everyday cooking</p><h1>A simple pantry pairing.</h1><p>Dry lentils and rice are independent products. Read the preparation notes and choose each pack separately.</p>{link('Read preparation notes '+I('ArrowRight'),'05-product-facts')}</div>{image('staples-still-life','Uncooked rice and lentils; pantry inspiration, not a sold meal')}</section><section class="section"><div class="section-head"><div><h2>Also on the shelf</h2><p>Independently priced. No bundle or automatic add.</p></div></div><div class="shelf-grid">{row(True)}<div class="panel"><h3>Shipping & product support</h3><p>Available rates depend on the delivery address and are shown before payment.</p><p>For a damaged pack or a product question, contact Pantry with your order reference. Any return eligibility must follow the merchant’s published policy.</p>{link('View an owned order','14-order-detail')}</div></div></section><div class="facts-inline"><div><h3>Pack count ≠ net quantity</h3><p>2 × 250 g is two packs and 500 g total net.</p></div><div><h3>No supplied allergen data</h3><p>Ask first if you need a dietary decision.</p></div><div><h3>Shipping at checkout</h3><p>No estimated delivery date is promised here.</p></div></div></main>'''+footer(),'/products/split-red-lentils#continuation','Keep recipe education, independent related products and actual policy references separate from invented bundle/fulfillment capability.')
add('07-cart','Cart · pack quantities & totals',header()+f'''<main id="main" class="wrap">{crumb('Your cart')}<div class="section-head"><div><p class="eyebrow">Ready for your shelf</p><h1>Your cart</h1><p style="margin-top:14px">3 packs · 1.5 kg total net</p></div>{link('Continue shopping '+I('ArrowRight'),'03-collection')}</div><div class="split"><section>{line()}{line(True)}{info('Could not update the pack quantity','Your previous quantity is retained. Check your connection and retry; totals refresh after the server confirms.','error')}<div class="panel"><h3>Keep the pack details</h3><p>Split red lentils: 2 × 250 g = 500 g net.<br>Basmati rice: 1 × 1 kg = 1 kg net.</p>{link('Return to lentil details','04-product-main')}</div></section>{summary(False)}</div></main>'''+footer(),'/cart','Review named SKUs, independent quantity/remove controls and recoverable server-update failure before hosted checkout.')
def checkout_head():return f'<header class="checkout-head"><div class="wrap"><div><a class="wordmark" href="01-home-top.html"><b>pantry.</b></a><p>Shared checkout by LetBuyy</p></div><div><span class="status">Mock provider · visual fixture</span><p style="margin-top:7px">{I("LockKeyhole")} checkout.letbuyy.com</p></div></div></header>'
add('08-checkout-address','Shared checkout · contact, address & shipping',checkout_head()+f'''<main id="main" class="wrap checkout-main"><nav class="progress">{link('Cart','07-cart','')} {I('ChevronRight')} <strong>1 Address</strong> {I('ChevronRight')} <span>2 Review & pay</span></nav><div class="split"><section><h1>Where should it go?</h1><div class="section-head"><h3>Contact</h3>{link('Sign in with LetBuyy','10-sign-in')}</div>{field('Email','mira@example.test','email')}<h3 style="margin:20px 0">Delivery address</h3><div class="form-grid">{field('First name','Mira')}{field('Last name','Example')}{'<div class="span">'+field('Address','14 Sample Lane, Flat 2')+'</div>'}{field('Area (optional)','Example Nagar')}{field('City','Bengaluru')}{field('State','Karnataka')}{field('PIN code','560001')}</div><p class="small muted">India · fictional address fixture</p><h3 style="margin:24px 0 14px">Shipping</h3><label class="method"><input type="radio" checked name="shipping"><div><strong>Standard shipping</strong><p>Available for this sample address. Delivery estimate not supplied.</p></div><b>₹60</b></label><p class="small muted">Changing the address recalculates eligible rates.</p><div style="margin-top:26px">{B('Review order & payment','09-checkout-review')}</div></section>{summary(True,True)}</div></main>''','checkout.letbuyy.com/checkout#address','Use the canonical hosted address/quote owner; display full pack identity and no unsupported ETA.')
add('09-checkout-review','Shared checkout · review & payment recovery',checkout_head()+f'''<main id="main" class="wrap checkout-main"><nav class="progress">{link('1 Address','08-checkout-address','')}{I('ChevronRight')}<strong>2 Review & pay</strong></nav><h1>Check every detail.</h1><div class="split review"><section><div class="panel"><div class="section-head"><h3>Contact & delivery</h3>{link('Change','08-checkout-address')}</div><p>mira@example.test</p>{address}<div class="fact"><strong>Standard shipping · ₹60</strong><p>Delivery estimate not supplied.</p></div></div><h2 style="font-size:27px;margin:28px 0 15px">Payment</h2><p class="small">Eligible methods from this sample quote. Your live choices depend on the merchant and address.</p><label class="method"><input type="radio" checked name="payment"><div><strong>Online payment</strong><p>Continue to the merchant’s provider for available UPI/card options. Mock mode in this reference.</p></div></label><label class="method"><input type="radio" name="payment"><div><strong>Cash on delivery</strong><p>Eligible in this fixture; confirmation may be required.</p></div></label>{info('Payment did not start','No payment has been confirmed. Review the order and retry with your details retained.','error')}<p class="small">By continuing, you agree to the merchant’s applicable purchase and shipping terms.</p><div style="margin:20px 0">{link('Retry online payment · ₹640 '+I('ArrowRight'),'09-checkout-review','button full')}</div><p class="small muted">Payment status comes from the provider and server confirmation.</p></section>{summary(True,True)}</div></main>''','checkout.letbuyy.com/checkout#review','Review all lines/totals before commitment; render eligible mock methods and an explicit recoverable payment-start error.')
