add('10-sign-in','LetBuyy buyer sign-in · Pantry destination',f'''<div class="auth">{auth_top()}<main id="main" class="auth-card">{destination()}<h1>Sign in to LetBuyy</h1><p>Use your buyer account to continue to Pantry.</p>{field('Email','mira@example.test','email')}{field('Password','','password')}{link('Forgot password?','10-sign-in')}<button class="primary">Sign in</button><div class="auth-note">New to LetBuyy? {link('Create an account','11-sign-up')}<p style="margin:12px 0 0;font-size:13px">Pantry can see the orders you place with Pantry. Signing in does not grant merchant access.</p></div><details><summary>Session expired state</summary>{info('Sign in again','Your Pantry destination is retained. Only safe form data is preserved.')}</details></main><div class="auth-footer">LetBuyy buyer identity · Privacy · Terms · Help</div></div>''','identity.letbuyy.com/buyer/authorize','Keep credentials within the sole LetBuyy buyer issuer, explicit destination and recovery context.')
add('11-sign-up','LetBuyy create account · verification & consent',f'''<div class="auth">{auth_top()}<main id="main" class="auth-card">{destination()}<h1>Create your LetBuyy account</h1><p>One buyer identity. A clear return to Pantry.</p>{field('Email','mira@example.test','email')}{field('Password','','password')}<p class="small">Use at least 8 characters. The server enforces the current password requirements.</p><button class="primary">Create account</button><div class="auth-note"><strong>Verification & account protection</strong><p class="small" style="margin:9px 0">Complete the LetBuyy security check when requested. Account creation does not itself connect you to Pantry.</p></div><div class="info"><div><strong>Next: Continue to Pantry</strong><p>Review the signed-in email and explicitly continue. Pantry receives your email through LetBuyy’s store authorization. Use a different account if needed.</p></div></div><section class="auth-note"><p class="eyebrow">After successful account creation</p><h2 style="font-size:25px;margin:12px 0">Continue to Pantry</h2><p class="small" style="margin:10px 0">You’re signed in to LetBuyy as <strong>mira@example.test</strong>. Pantry will receive your email address.</p>{link('Continue to Pantry','12-profile','button full')}<div style="margin-top:10px">{link('Use a different account','10-sign-in')}</div></section>{link('Already have an account? Sign in','10-sign-in')}</main><div class="auth-footer">LetBuyy buyer identity · Privacy · Terms · Help</div></div>''','identity.letbuyy.com/buyer/authorize?screen=register','Show canonical registration and actual security check and explicit account-sharing continuation requirement without inventing verification codes or providers.')
add('12-profile','Your Pantry account · overview & profile',account_shell('Hello, Mira.','Your details and orders at Pantry.','Overview',f'''<h2>Account overview</h2><div class="account-cards"><section class="panel"><p class="eyebrow">Personal details</p><h3>Mira Example</h3><p>mira@example.test</p>{link('Edit profile','12-profile')}</section><section class="panel"><p class="eyebrow">Recent order</p><h3>PN-1048 · ₹640</h3><p>22 Oct 2026 · Confirmed in mock fixture</p>{link('View order '+I('ArrowRight'),'14-order-detail')}</section></div><section class="panel"><h3>Edit your display name</h3><div class="form-grid" style="margin-top:20px">{field('First name','Mira')}{field('Last name','Example')}</div><button class="primary">Save profile</button><p class="small" style="margin-top:14px">Account email and verification are managed through LetBuyy.</p></section>{info('Your Pantry view','Orders shown here belong to your buyer account at Pantry. Other stores’ orders are not included.')}<section class="panel"><h3>Default delivery address</h3>{address}{link('Manage saved addresses','15-addresses')}</section>'''),'/account','Allow supported profile editing and tenant-scoped navigation; distinguish buyer identity from store relationship.')
order_card=f'''<article class="panel"><div class="order-header"><div><p class="eyebrow">22 October 2026</p><h3>Order PN-1048</h3><p class="small">3 packs · ₹640</p></div><span class="status">Confirmed · mock fixture</span></div><div class="order-thumbs">{image('red-lentils','Red lentils')}{image('basmati-rice','Rice')}</div><p>Split red lentils · 250 g × 2<br>Basmati rice · 1 kg × 1</p><div class="order-actions">{link('View order '+I('ArrowRight'),'14-order-detail','button secondary')}<span class="small muted">Shipping ₹60 · tax included</span></div></article>'''
add('13-orders','Your orders · history',account_shell('Your orders','Orders placed with Pantry using this buyer account.','Orders',f'''<div class="section-head"><h2>Order history</h2><select aria-label="Order period"><option>All time</option></select></div>{order_card}<div class="pagination"><p>1 order · Page 1 of 1</p><a href="13-orders.html" aria-current="page">1</a></div><div class="panel"><h3>Looking for an order?</h3><p>Check you signed in with the email used at checkout. Guest orders require the existing verification path before they are shown.</p>{link('Account details','12-profile')}</div>'''),'/account/orders','Identify owned orders clearly with pack variants, pagination and safe missing-order recovery.')
add('14-order-detail','Order PN-1048 · owned detail',account_shell('Order PN-1048','Placed 22 October 2026 · Fictional order reference','Orders',f'''<div class="section-head"><h2>Your pantry order</h2><span class="status">Mock provider · visual fixture</span></div><div class="timeline"><div><strong>{I('Check')} Confirmed</strong><p>22 Oct 2026</p></div><div><strong>Not dispatched</strong><p>No carrier event supplied</p></div><div><strong>Delivery pending</strong><p>No delivery date supplied</p></div></div>{order_line()}{order_line(True)}<div class="account-cards" style="margin-top:26px"><section class="panel"><h3>Delivery details</h3>{address}<p class="small">Standard shipping · ₹60</p></section><section class="panel"><h3>Order totals</h3><div class="summary-row"><span>Items</span><span>₹580</span></div><div class="summary-row"><span>Shipping</span><span>₹60</span></div><div class="summary-row"><span>Tax</span><span>Included</span></div><div class="summary-row total"><span>Total</span><span>₹640</span></div><p class="small">Payment confirmed in mock fixture.<br>No real payment or order was created.</p></section></div><section class="panel"><h3>A question about your order?</h3><p>Contact the merchant with reference PN-1048. Return or cancellation eligibility depends on the actual order and published policy.</p>{link('Back to order history','13-orders')}</section>'''),'/account/orders/PN-1048','Read exact selected SKU, pack count, net weight, totals and truthful mock fulfillment/payment states for owned order only.')
add('15-addresses','Saved addresses · edit, validation & default',account_shell('Saved addresses','Choose a default and keep delivery details current.','Addresses',f'''<div class="account-cards"><section class="panel"><span class="status">Default address</span><h3 style="margin-top:16px">Home</h3>{address}<div style="display:flex;gap:22px">{link('Edit','15-addresses')}{link('Remove','15-addresses')}</div></section><section class="panel"><h3>Add another address</h3><p>Save an address for future checkout. Serviceability is checked for each order.</p>{link(I('Plus')+' Add address','15-addresses','button secondary')}</section></div><section class="panel sheet"><div class="section-head"><div><p class="eyebrow">Representative edit state</p><h2>Edit home address</h2></div>{link('Cancel','15-addresses')}</div><div class="form-grid">{field('First name','Mira')}{field('Last name','Example')}{'<div class="span">'+field('Address','14 Sample Lane, Flat 2')+'</div>'}{field('Area (optional)','Example Nagar')}{field('City','Bengaluru')}{field('State','Karnataka')}{field('PIN code','56001',error=True)}</div><p id="pin-error" style="color:var(--error);font-size:14px">Enter a 6-digit Indian PIN code. Your edits are retained.</p><label class="check"><input type="checkbox" checked><span>Use as my default address</span></label><div style="display:flex;gap:20px;flex-wrap:wrap"><button class="primary">Save address</button>{link('Cancel editing','15-addresses')}</div></section>{info('Address ownership','Only addresses owned by your signed-in buyer account are available. A session expiry asks you to sign in again; it does not expose another buyer’s address.')}'''),'/account/addresses','Show list plus supported add/edit/default controls with precise retained-input validation.')
rice_body=header()+f'''<main id="main" class="wrap">{crumb('Basmati rice')}<div class="pdp-grid"><div class="pdp-photo">{image('basmati-rice','Whole unprinted basmati rice pouch')}</div><section class="ingredients"><h2>Inside the pack</h2><div class="fact"><strong>Ingredients</strong><p>Basmati rice (100%).</p></div>{info('Allergen information not supplied','Ask the merchant before buying if you need this information.','warning')}<div class="fact"><strong>Storage</strong><p>Store in a cool, dry place; keep airtight after opening.</p></div></section><section class="purchase"><p class="eyebrow">Rice & grains</p><h1>Basmati rice</h1><div class="price">₹220 / pack</div><p>1 kg net · ₹22 / 100 g · tax included</p><p>SKU P-RICE-1K · Single pack size</p><div class="pack-math"><strong>1 pack · 1 kg total net · ₹220</strong></div>{B('View cart with this rice','07-cart')}{link('Return to lentil pairings','06-product-continuation')}</section></div></main>'''+footer()
(S/'product-rice.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Basmati rice · supplementary original product</title><link rel="stylesheet" href="styles.css"><body>'+rice_body+'<script src="prototype.js"></script></body></html>')
(R/'scenes.json').write_text(json.dumps(scenes,indent=2)+'\n')
(S/'prototype.js').write_text('''// Visual reference only. No network requests, persistence, account or payment effects.
if(new URLSearchParams(location.search).has('neutral'))document.body.classList.add('neutral');
document.querySelectorAll('button').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();let n=document.getElementById('prototype-status');if(!n){n=document.createElement('p');n.id='prototype-status';n.setAttribute('role','status');n.className='info';b.parentNode.append(n)}n.textContent='Visual reference control. Canonical integration is required before this can perform an action.'}));
''')
(R/'prototype-index.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pantry source scenes</title><style>body{font:17px/1.6 system-ui;max-width:850px;margin:40px auto;padding:20px}a{display:block;padding:12px;color:#36533d}</style><h1>Pantry · responsive presentation source</h1><p>Visual fixture only. No API, account, order or payment effects. Scenes 01+02 form one homepage; 04+05+06 form one PDP.</p>'+''.join(f'<a href="{s["source"]}">{s["id"]} · {s["title"]}</a>' for s in scenes)+'</html>')
print('Built',len(scenes),'connected scene files')
